"use client";

import React from "react";
import { motion } from "framer-motion";
import { AlertCircle, ImageIcon, MessageSquare } from "lucide-react";
import { Nav } from "@/components/layout/nav";
import { Footer } from "@/components/layout/footer";
import { HeroSection } from "@/components/shared/hero-section";
import { StatStrip } from "@/components/shared/stat-strip";
import { FAQAccordion } from "@/components/shared/faq-accordion";
import { CTASection } from "@/components/shared/cta-section";
import { SectionEyebrow } from "@/components/shared/section-eyebrow";
import { BRAND, FONT, SHADOW, GRADIENT, ACCENT_MAP } from "@/lib/brand";
import type { AccentKey } from "@/lib/brand";

// ─── Types ────────────────────────────────────────────────────────────────────

interface MoatCardProps {
  accent: AccentKey;
  icon: React.ComponentType<{ size?: number; color?: string; strokeWidth?: number }>;
  title: string;
  body: string;
  detail: [string, string][];
  delay?: number;
}

// ─── MoatCard ─────────────────────────────────────────────────────────────────

function MoatCard({ accent, icon: Icon, title, body, detail, delay = 0 }: MoatCardProps) {
  const a = ACCENT_MAP[accent];
  return (
    <motion.div
      initial={{ opacity: 0, y: 16 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5, delay }}
      whileHover={{ y: -4, boxShadow: SHADOW.card }}
      style={{
        background: BRAND.white,
        borderRadius: 18,
        padding: 28,
        boxShadow: SHADOW.soft,
        display: "flex",
        flexDirection: "column",
        gap: 18,
        position: "relative",
        overflow: "hidden",
        transition: "transform 0.25s, box-shadow 0.25s",
      } as React.CSSProperties}
    >
      {/* Top accent strip */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: 3,
          background: a.color,
        } as React.CSSProperties}
      />

      {/* Corner glow */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          top: 0,
          right: 0,
          width: 120,
          height: 120,
          background: `radial-gradient(circle at 100% 0%, ${a.bg} 0%, transparent 70%)`,
          pointerEvents: "none",
        } as React.CSSProperties}
      />

      {/* Icon */}
      <div style={{ position: "relative" } as React.CSSProperties}>
        <div
          style={{
            width: 48,
            height: 48,
            borderRadius: 12,
            background: a.glow,
            border: `1px solid ${a.color}25`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          } as React.CSSProperties}
        >
          <Icon size={20} color={a.color} strokeWidth={2} />
        </div>
      </div>

      {/* Text */}
      <div style={{ position: "relative" } as React.CSSProperties}>
        <h3
          style={{
            fontFamily: FONT.sans,
            fontSize: 19,
            fontWeight: 600,
            color: BRAND.onyx,
            letterSpacing: "-0.015em",
            marginBottom: 10,
            lineHeight: 1.25,
          } as React.CSSProperties}
        >
          {title}
        </h3>
        <p
          style={{
            fontFamily: FONT.sans,
            fontSize: 14,
            fontWeight: 400,
            lineHeight: 1.6,
            color: BRAND.stoneDark,
          } as React.CSSProperties}
        >
          {body}
        </p>
      </div>

      {/* Detail block */}
      <div
        style={{
          background: a.bg,
          borderRadius: 12,
          padding: "4px 16px",
          marginTop: "auto",
          position: "relative",
        } as React.CSSProperties}
      >
        {detail.map((row, i) => (
          <div
            key={i}
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "baseline",
              padding: "10px 0",
              borderBottom: i < detail.length - 1 ? `1px dashed ${a.color}25` : "none",
              gap: 12,
            } as React.CSSProperties}
          >
            <span
              style={{
                fontFamily: FONT.sans,
                fontSize: 11.5,
                fontWeight: 500,
                color: BRAND.stoneDark,
              } as React.CSSProperties}
            >
              {row[0]}
            </span>
            <span
              style={{
                fontFamily: FONT.sans,
                fontSize: 12,
                fontWeight: 600,
                color: BRAND.onyx,
                textAlign: "right",
              } as React.CSSProperties}
            >
              {row[1]}
            </span>
          </div>
        ))}
      </div>
    </motion.div>
  );
}

// ─── AnatomySection ───────────────────────────────────────────────────────────

function AnatomySection() {
  return (
    <section
      style={{
        background: GRADIENT.sectionWarm,
        paddingTop: 100,
        paddingBottom: 100,
        position: "relative",
        overflow: "hidden",
      } as React.CSSProperties}
    >
      <div
        style={{
          maxWidth: 1280,
          margin: "0 auto",
          padding: "0 32px",
        } as React.CSSProperties}
      >
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6 }}
          style={{ marginBottom: 48, maxWidth: 680 } as React.CSSProperties}
        >
          <SectionEyebrow label="What's on the record" accent="amber" />
          <h2
            style={{
              fontFamily: FONT.sans,
              fontSize: "clamp(28px, 3.5vw, 44px)",
              fontWeight: 700,
              color: BRAND.onyx,
              letterSpacing: "-0.025em",
              lineHeight: 1.1,
            } as React.CSSProperties}
          >
            Three columns of intel.
          </h2>
        </motion.div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gap: 18,
          } as React.CSSProperties}
          className="v4-moat-grid"
        >
          <MoatCard
            accent="rust"
            icon={AlertCircle}
            title="Allergy intelligence"
            body="Red ink, latex, topical reactions — all linked to the client. Surfaces on Today, on the schedule card, in the artist's brief. Never buried."
            detail={[
              ["Surfaces in", "4 places"],
              ["Patch test log", "ON"],
              ["Last updated", "visible"],
            ]}
            delay={0}
          />
          <MoatCard
            accent="amber"
            icon={ImageIcon}
            title="Photo timeline"
            body="Every session has its photos: reference, fresh, healing, healed. Auto-organised by project, accessible from the client record."
            detail={[
              ["Stages tracked", "4"],
              ["Storage", "Supabase"],
              ["Auto-tag", "by session"],
            ]}
            delay={0.07}
          />
          <MoatCard
            accent="sage"
            icon={MessageSquare}
            title="Comms thread"
            body="Every SMS, email, and IG DM lives on the client record. Last touch surfaces on Today. Internal notes vs client-facing — clearly separated."
            detail={[
              ["Channels", "4"],
              ["Internal notes", "YES"],
              ["Auto-archive", "90d"],
            ]}
            delay={0.14}
          />
        </div>
      </div>
    </section>
  );
}

// ─── ScreenshotSection ────────────────────────────────────────────────────────

function ScreenshotSection() {
  return (
    <section
      style={{
        background: BRAND.bone,
        paddingTop: 80,
        paddingBottom: 80,
      } as React.CSSProperties}
    >
      <div
        style={{
          maxWidth: 1280,
          margin: "0 auto",
          padding: "0 32px",
        } as React.CSSProperties}
      >
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-60px" }}
          transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
          style={{
            borderRadius: 20,
            overflow: "hidden",
            height: 420,
            background: `linear-gradient(135deg, ${BRAND.rust} 0%, ${BRAND.amber} 100%)`,
            display: "flex",
            alignItems: "flex-end",
            padding: "0 32px 28px",
            position: "relative",
            boxShadow: SHADOW.hero,
          } as React.CSSProperties}
        >
          {/* Decorative inner glow */}
          <div
            aria-hidden="true"
            style={{
              position: "absolute",
              inset: 0,
              background: "radial-gradient(ellipse 70% 50% at 30% 30%, rgba(255,255,255,0.12) 0%, transparent 60%)",
              pointerEvents: "none",
            } as React.CSSProperties}
          />
          {/* Grid lines */}
          <div
            aria-hidden="true"
            style={{
              position: "absolute",
              inset: 0,
              backgroundImage: `linear-gradient(rgba(255,255,255,0.04) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.04) 1px, transparent 1px)`,
              backgroundSize: "48px 48px",
              pointerEvents: "none",
            } as React.CSSProperties}
          />
          <div
            style={{
              position: "relative",
              fontFamily: FONT.sans,
              fontSize: 13,
              fontWeight: 500,
              color: "rgba(255,255,255,0.85)",
              letterSpacing: "0.01em",
            } as React.CSSProperties}
          >
            Client profile · Asha Mehra · Koi sleeve project · 4 sessions
          </div>
        </motion.div>
      </div>
    </section>
  );
}

// ─── ProofSection ─────────────────────────────────────────────────────────────

function ProofSection() {
  return (
    <section
      style={{
        background: BRAND.boneCream,
        paddingTop: 60,
        paddingBottom: 60,
      } as React.CSSProperties}
    >
      <div
        style={{
          maxWidth: 1280,
          margin: "0 auto",
          padding: "0 32px",
        } as React.CSSProperties}
      >
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-60px" }}
          transition={{ duration: 0.55 }}
        >
          <StatStrip
            items={[
              { stat: "Per-client", label: "allergy + medical fields" },
              { stat: "GDPR-ready", label: "data export + delete" },
              { stat: "Cross-channel", label: "comms unified" },
              { stat: "Photo storage", label: "unlimited per project" },
            ]}
          />
        </motion.div>
      </div>
    </section>
  );
}

// ─── FAQSection ───────────────────────────────────────────────────────────────

const faqs = [
  {
    q: "Can I export a single client's full record?",
    a: "Yes. PDF export pulls every session, photo, consent, communication, and allergy field for one client. GDPR Article 15 ready.",
  },
  {
    q: "How does allergy data get into the system?",
    a: "Three ways: artist input, client kiosk form, ongoing chair updates. Every change is timestamped and audit-logged.",
  },
  {
    q: "Do photos count against any storage limit?",
    a: "No. Photo storage is unlimited on every paid plan.",
  },
  {
    q: "Can a guest artist see clients I've worked with?",
    a: "Only if you grant access. Default is per-artist scoping. Studio owners see all.",
  },
];

function FAQSection() {
  return (
    <section
      style={{
        background: GRADIENT.sectionCool,
        paddingTop: 100,
        paddingBottom: 100,
      } as React.CSSProperties}
    >
      <div
        style={{
          maxWidth: 1120,
          margin: "0 auto",
          padding: "0 24px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
        } as React.CSSProperties}
      >
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6 }}
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            marginBottom: 48,
          } as React.CSSProperties}
        >
          <SectionEyebrow label="Common questions" accent="rust" />
          <h2
            style={{
              fontFamily: FONT.sans,
              fontSize: "clamp(26px, 3.2vw, 40px)",
              fontWeight: 700,
              color: BRAND.onyx,
              letterSpacing: "-0.025em",
              lineHeight: 1.1,
              textAlign: "center",
            } as React.CSSProperties}
          >
            The record, answered.
          </h2>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-60px" }}
          transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
          style={{ maxWidth: 920, width: "100%", margin: "0 auto" } as React.CSSProperties}
        >
          <FAQAccordion items={faqs} accent="rust" />
        </motion.div>
      </div>
    </section>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function ClientsPage() {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: BRAND.bone,
        overflow: "hidden",
      } as React.CSSProperties}
    >
      <Nav />
      <main>
        <HeroSection
          eyebrow="Clients"
          eyebrowAccent="rust"
          headline="Every client. Every session. One quiet record."
          italicWord="record"
          subhead="Photo timelines. Allergy intelligence. Consent history. Communication thread. The CRM that knows the difference between a touch-up and a sleeve."
          primaryCTA={{ label: "Start a 14-day trial", href: "https://inkos.up.railway.app/signup" }}
          secondaryCTA={{ label: "Book a walkthrough", href: "/book-a-demo", icon: "play" }}
        />

        <AnatomySection />

        <ScreenshotSection />

        <ProofSection />

        <FAQSection />

        <CTASection
          badge="The client, fully held"
          headline="See the record live."
          italicWord="record"
          subhead="14-day trial. Add your first client. Watch the allergy banner light up Today."
          primaryCTA={{ label: "Start a 14-day trial", href: "https://inkos.up.railway.app/signup" }}
          secondaryCTA={{ label: "Book a walkthrough", href: "/book-a-demo", icon: "play" }}
        />
      </main>
      <Footer />
    </div>
  );
}

